package dev.bennett.codexmeter;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import org.json.*;
/** Actual production RemoteViews on the owned emulator; no user data writes. */
public final class TaskWidgetGridNativeTest extends Instrumentation {
 int checks;void check(boolean v,String text){checks++;if(!v)throw new AssertionError(text);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{check(Build.MODEL.contains("sdk"),"Emulator only");android.content.Context c=getTargetContext();long now=System.currentTimeMillis();JSONArray rows=new JSONArray();for(int i=0;i<6;i++)rows.put(new JSONObject().put("name","GPT HUD 개발 작업 "+(i+1)).put("thread",String.format("%032x",i)).put("state",i%3==0?"running":i%3==1?"completed":"interrupted").put("at",now));JSONObject data=new JSONObject().put("verified",true).put("checked",now).put("rows",rows);
 final Throwable[] failed={null};runOnMainSync(()->{try{render(c,data,now,320,180,4);render(c,data,now,320,240,6);render(c,data,now,200,240,3);
  View stale=TaskStatusWidget.render(c,320,180,2,data,now-180000,true).apply(c,new FrameLayout(c));LinearLayout tasks=stale.findViewById(R.id.task_status_tasks);TextView state=tasks.getChildAt(0).findViewById(R.id.task_status_state);check(!state.getText().toString().equals(c.getString(R.string.task_trial_running)),"Disconnected never claims running");check(state.getCurrentTextColor()==0xffa7adb5,"Stale gray");
 }catch(Throwable e){failed[0]=e;}});if(failed[0]!=null)throw failed[0];
 String account=LanSync.account(c);check(account.equals(hash("refinement-production-fixture-account")),"Owned synthetic account only");
 android.content.SharedPreferences prefs=c.getSharedPreferences("codex_task_trial",0);check(!prefs.contains(account)&&!prefs.contains(account+"_on"),"Never overwrite existing task data");
 try{prefs.edit().putBoolean(account+"_on",true).commit();JSONObject incoming=new JSONObject().put("epoch","00000000000000000000000000000000").put("device",hash("synthetic-pc")).put("source","local_log_trial").put("checked",now).put("verified",true);JSONArray raw=new JSONArray();for(int i=0;i<6;i++)raw.put(new JSONObject().put("Thread",String.format("%032x",i)).put("Turn",String.format("%032x",i+20)).put("State","running").put("Name","Synthetic task "+i).put("At",now).put("Seen",now).put("Sequence",6-i));incoming.put("rows",raw);TaskStatusStore.save(c,account,incoming);
  for(int i=3;i<6;i++){String previous=TaskStatusStore.widgetText(c,6);raw.getJSONObject(i).put("State","completed");TaskStatusStore.save(c,account,incoming);check(!previous.equals(TaskStatusStore.widgetText(c,6)),"Fourth-sixth task change reaches update fingerprint "+i);}
 }finally{prefs.edit().remove(account).remove(account+"_on").remove(account+"_received").commit();}
 out.putString("stream","Task widget native: "+checks+" checks passed; actual RemoteViews and store, synthetic emulator.\n");finish(-1,out);}catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));finish(0,out);}}
 String hash(String value)throws Exception{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b&255));return s.toString();}
 void render(android.content.Context c,JSONObject data,long now,int width,int height,int expected)throws Exception {View v=TaskStatusWidget.render(c,width,height,2,data,now,true).apply(c,new FrameLayout(c));float density=c.getResources().getDisplayMetrics().density;int w=(int)(width*density),h=(int)(height*density);v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);LinearLayout tasks=v.findViewById(R.id.task_status_tasks);int count=0;for(int i=0;i<tasks.getChildCount();i++){LinearLayout row=(LinearLayout)tasks.getChildAt(i);check(row.getBottom()<=tasks.getHeight(),"No clipped row");for(int j=0;j<row.getChildCount();j++){View cell=row.getChildAt(j);check(cell.getWidth()>0,"Visible weighted cell");TextView state=cell.findViewById(R.id.task_status_state);check(state.getLineCount()==1,"Compact state");check(state.getBottom()<=cell.getHeight()-cell.getPaddingBottom(),"State view fits cell");check(state.getBaseline()+state.getPaint().getFontMetricsInt().descent<=state.getHeight()-state.getCompoundPaddingBottom(),"State glyph not clipped: "+width+"x"+height+" row="+i+" cell="+j+" baseline="+state.getBaseline()+" descent="+state.getPaint().getFontMetricsInt().descent+" height="+state.getHeight());count++;}}check(count==expected,"Expected task count "+expected);if(width==320&&height==180){Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(FileOutputStream f=new FileOutputStream(new File(c.getExternalFilesDir(null),"task-grid-5x3.png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}}
}
